INSERT INTO "ReporteFalla" VALUES (1,18,1774962775159,'Freddy ','El taladro se calienta y se apaga cada cierto tiempo ','Media','Pendiente');
INSERT INTO "ReporteFalla" VALUES (2,8,1775496663886,'JEFE DE PLANTA','LA PANTALLA DEL CONTROL SE PONE OSCURA CUANDO SE ENCIENDE LA MAQUINA Y SE DEMORA EN APARECER LAS LETRAS, SOLO CUANDO SE CALIENTA SE VE BIEN, PERO DESPUES DEL 01/04 LA LUZ SE FUE QUEDANDO MAS OSCURA.','Media','Pendiente');
INSERT INTO "ReporteFalla" VALUES (3,12,1775496773429,'LUIS','LA MAQUINA NECESITA MANTENIMIENTO, SE REPORTARON QUE LAS CORREAS ESTA PARA CAMBIO TIENE MULTIPLES FUGAS DE ACEITE Y AIRE Y EXCESO DE MATERIAL PARTICULADO','Media','Pendiente');
