BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "Alerta" (
	"id" SERIAL NOT NULL,
	"tipo"	TEXT NOT NULL,
	"mensaje"	TEXT NOT NULL,
	"fecha"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"leida"	BOOLEAN NOT NULL DEFAULT false,
	"proyecto_id"	INTEGER,
	"maquina_id"	INTEGER,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "ArchivoAdjunto" (
	"id" SERIAL NOT NULL,
	"proyecto_id"	INTEGER NOT NULL,
	"nombre_archivo"	TEXT NOT NULL,
	"url_archivo"	TEXT NOT NULL,
	"fecha_carga"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "ArchivoAdjunto_proyecto_id_fkey" FOREIGN KEY("proyecto_id") REFERENCES "ProyectoEspecial"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "CargaMaquina" (
	"id" SERIAL NOT NULL,
	"maquina_id"	INTEGER NOT NULL,
	"proyecto_id"	INTEGER,
	"horas_asignadas"	DECIMAL NOT NULL,
	"semana"	INTEGER NOT NULL,
	"ano"	INTEGER NOT NULL,
	PRIMARY KEY("id"),
	CONSTRAINT "CargaMaquina_maquina_id_fkey" FOREIGN KEY("maquina_id") REFERENCES "Maquina"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
	CONSTRAINT "CargaMaquina_proyecto_id_fkey" FOREIGN KEY("proyecto_id") REFERENCES "ProyectoEspecial"("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Cliente" (
	"id" SERIAL NOT NULL,
	"nombre"	TEXT NOT NULL,
	"contacto"	TEXT,
	"direccion"	TEXT,
	"calificacion"	DECIMAL DEFAULT 0,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "Configuracion" (
	"id" SERIAL NOT NULL,
	"max_proyectos_activos"	INTEGER NOT NULL DEFAULT 10,
	"nombre_empresa"	TEXT DEFAULT 'MI EMPRESA SAS',
	"nit_empresa"	TEXT DEFAULT '000.000.000-0',
	"direccion_empresa"	TEXT,
	"telefono_empresa"	TEXT,
	"email_empresa"	TEXT,
	"densidad_acero_default"	DECIMAL DEFAULT 7.85,
	"horas_turno_default"	DECIMAL DEFAULT 8,
	"openrouter_api_key"	TEXT,
	"openrouter_model"	TEXT DEFAULT 'google/gemma-3-27b-it:free',
	"unidad_longitud"	TEXT NOT NULL DEFAULT 'mm',
	"unidad_peso"	TEXT NOT NULL DEFAULT 'kg',
	"unidad_volumen"	TEXT NOT NULL DEFAULT 'litros',
	"decimales_produccion"	INTEGER NOT NULL DEFAULT 2,
	"decimales_costos"	INTEGER NOT NULL DEFAULT 2,
	"decimales_medidas"	INTEGER NOT NULL DEFAULT 2,
	"umbral_stock_minimo"	DECIMAL NOT NULL DEFAULT 10,
	"dias_retraso_alerta"	INTEGER NOT NULL DEFAULT 1,
	"frecuencia_alertas"	TEXT NOT NULL DEFAULT 'Inmediata',
	"alarma_retraso_ot"	BOOLEAN NOT NULL DEFAULT true,
	"alarma_bajo_stock"	BOOLEAN NOT NULL DEFAULT true,
	"alarma_mantenimiento"	BOOLEAN NOT NULL DEFAULT true,
	"alarma_fases_proyecto"	BOOLEAN NOT NULL DEFAULT true,
	"updatedAt"	TIMESTAMP NOT NULL,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "ConfiguracionUsuario" (
	"id" SERIAL NOT NULL,
	"usuario_id"	INTEGER NOT NULL,
	"tema"	TEXT NOT NULL DEFAULT 'Automático',
	"color_primario"	TEXT NOT NULL DEFAULT '#2563eb',
	"color_secundario"	TEXT NOT NULL DEFAULT '#475569',
	"color_superficie"	TEXT NOT NULL DEFAULT '#ffffff',
	"color_borde"	TEXT NOT NULL DEFAULT '#e2e8f0',
	"color_texto"	TEXT NOT NULL DEFAULT '#0f172a',
	"notificaciones_app"	BOOLEAN NOT NULL DEFAULT true,
	"notificaciones_email"	BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id"),
	CONSTRAINT "ConfiguracionUsuario_usuario_id_fkey" FOREIGN KEY("usuario_id") REFERENCES "Usuario"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ConsumibleMaquina" (
	"id" SERIAL NOT NULL,
	"maquina_id"	INTEGER NOT NULL,
	"nombre"	TEXT NOT NULL,
	"vida_util_dias"	INTEGER,
	"cantidad_instalada"	DECIMAL,
	"fecha_ultimo_cambio"	TIMESTAMP,
	"fecha_proximo_cambio"	TIMESTAMP,
	"createdAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "ConsumibleMaquina_maquina_id_fkey" FOREIGN KEY("maquina_id") REFERENCES "Maquina"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "DotacionEPP" (
	"id" SERIAL NOT NULL,
	"personal_id"	INTEGER NOT NULL,
	"item"	TEXT NOT NULL,
	"cantidad"	INTEGER NOT NULL,
	"fecha_entrega"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"comentarios"	TEXT,
	PRIMARY KEY("id"),
	CONSTRAINT "DotacionEPP_personal_id_fkey" FOREIGN KEY("personal_id") REFERENCES "Personal"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "FaseProyecto" (
	"id" SERIAL NOT NULL,
	"proyecto_id"	INTEGER NOT NULL,
	"nombre"	TEXT NOT NULL,
	"responsable"	TEXT NOT NULL,
	"horas_estimadas"	DECIMAL NOT NULL,
	"horas_reales"	DECIMAL,
	"fecha_inicio"	TIMESTAMP NOT NULL,
	"fecha_fin"	TIMESTAMP,
	"estado"	TEXT NOT NULL DEFAULT 'Pendiente',
	"observaciones"	TEXT,
	"maquina_id"	INTEGER,
	"personal_id"	INTEGER,
	"costo_operacion"	DECIMAL DEFAULT 0,
	"createdAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updatedAt"	TIMESTAMP NOT NULL,
	PRIMARY KEY("id"),
	CONSTRAINT "FaseProyecto_maquina_id_fkey" FOREIGN KEY("maquina_id") REFERENCES "Maquina"("id") ON DELETE SET NULL ON UPDATE CASCADE,
	CONSTRAINT "FaseProyecto_personal_id_fkey" FOREIGN KEY("personal_id") REFERENCES "Personal"("id") ON DELETE SET NULL ON UPDATE CASCADE,
	CONSTRAINT "FaseProyecto_proyecto_id_fkey" FOREIGN KEY("proyecto_id") REFERENCES "ProyectoEspecial"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "FotoMantenimiento" (
	"id" SERIAL NOT NULL,
	"mantenimiento_id"	INTEGER NOT NULL,
	"url"	TEXT NOT NULL,
	PRIMARY KEY("id"),
	CONSTRAINT "FotoMantenimiento_mantenimiento_id_fkey" FOREIGN KEY("mantenimiento_id") REFERENCES "MantenimientoPreventivo"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "HerramientaConsumible" (
	"id" SERIAL NOT NULL,
	"codigo"	TEXT,
	"nombre"	TEXT NOT NULL,
	"tipo"	TEXT NOT NULL,
	"cantidad_total"	INTEGER NOT NULL DEFAULT 0,
	"cantidad_disponible"	INTEGER NOT NULL DEFAULT 0,
	"estado"	TEXT NOT NULL DEFAULT 'DISPONIBLE',
	"ubicacion"	TEXT,
	"observaciones"	TEXT,
	"createdAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updatedAt"	TIMESTAMP NOT NULL,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "HistorialCambios" (
	"id" SERIAL NOT NULL,
	"proyecto_id"	INTEGER NOT NULL,
	"usuario_id"	INTEGER NOT NULL,
	"fecha"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"descripcion"	TEXT NOT NULL,
	PRIMARY KEY("id"),
	CONSTRAINT "HistorialCambios_proyecto_id_fkey" FOREIGN KEY("proyecto_id") REFERENCES "ProyectoEspecial"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
	CONSTRAINT "HistorialCambios_usuario_id_fkey" FOREIGN KEY("usuario_id") REFERENCES "Usuario"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ListaMateriales" (
	"id" SERIAL NOT NULL,
	"producto_id"	INTEGER NOT NULL,
	"materia_prima_id"	INTEGER NOT NULL,
	"cantidad_requerida"	DECIMAL NOT NULL,
	PRIMARY KEY("id"),
	CONSTRAINT "ListaMateriales_materia_prima_id_fkey" FOREIGN KEY("materia_prima_id") REFERENCES "MateriaPrima"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
	CONSTRAINT "ListaMateriales_producto_id_fkey" FOREIGN KEY("producto_id") REFERENCES "Producto"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "MantenimientoPreventivo" (
	"id" SERIAL NOT NULL,
	"maquina_id"	INTEGER NOT NULL,
	"plan_id"	INTEGER,
	"fecha_programada"	TIMESTAMP NOT NULL,
	"fecha_realizada"	TIMESTAMP,
	"tecnico_responsable"	TEXT,
	"checklist_completado"	BOOLEAN NOT NULL DEFAULT false,
	"estado"	TEXT NOT NULL DEFAULT 'Programado',
	"observaciones"	TEXT,
	"foto_url"	TEXT,
	"costo_mantenimiento"	DECIMAL DEFAULT 0,
	"createdAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "MantenimientoPreventivo_maquina_id_fkey" FOREIGN KEY("maquina_id") REFERENCES "Maquina"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
	CONSTRAINT "MantenimientoPreventivo_plan_id_fkey" FOREIGN KEY("plan_id") REFERENCES "PlanMantenimiento"("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Maquina" (
	"id" SERIAL NOT NULL,
	"codigo"	TEXT NOT NULL,
	"nombre"	TEXT,
	"area_produccion"	TEXT,
	"tipo"	TEXT,
	"marca"	TEXT,
	"modelo"	TEXT,
	"serial"	TEXT,
	"fecha_compra"	TIMESTAMP,
	"estado"	TEXT NOT NULL DEFAULT 'Operativa',
	"ubicacion"	TEXT,
	"responsable"	TEXT,
	"hoja_vida_url"	TEXT,
	"foto_url"	TEXT,
	"adquirida_en"	TEXT,
	"observaciones"	TEXT,
	"motor_hp"	TEXT,
	"consumo_mes"	TEXT,
	"capacidad_trabajo"	TEXT,
	"horas_maquina_mes"	TEXT,
	"horas_disponibles_semana"	DECIMAL DEFAULT 40,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "MateriaPrima" (
	"id" SERIAL NOT NULL,
	"sku_mp"	TEXT NOT NULL,
	"nombre_mp"	TEXT NOT NULL,
	"descripcion"	TEXT,
	"categoria_mp"	TEXT NOT NULL,
	"unidad_medida_stock"	TEXT NOT NULL,
	"stock_actual"	DECIMAL NOT NULL DEFAULT 0,
	"stock_reservado"	DECIMAL NOT NULL DEFAULT 0,
	"devoluciones"	DECIMAL NOT NULL DEFAULT 0,
	"punto_reorden"	DECIMAL NOT NULL DEFAULT 0,
	"costo_unitario"	DECIMAL DEFAULT 0,
	"espesor"	DECIMAL DEFAULT 0,
	"ancho"	DECIMAL DEFAULT 0,
	"largo"	DECIMAL DEFAULT 0,
	"densidad"	DECIMAL DEFAULT 7.85,
	"peso_unitario"	DECIMAL DEFAULT 0,
	"updatedAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "MaterialProyecto" (
	"id" SERIAL NOT NULL,
	"orden_trabajo_id"	INTEGER NOT NULL,
	"cantidad"	DECIMAL NOT NULL,
	"unidad"	TEXT NOT NULL,
	"descripcion"	TEXT NOT NULL,
	"especificaciones"	TEXT,
	"ancho_tira"	TEXT,
	"observaciones"	TEXT,
	PRIMARY KEY("id"),
	CONSTRAINT "MaterialProyecto_orden_trabajo_id_fkey" FOREIGN KEY("orden_trabajo_id") REFERENCES "OrdenTrabajo"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "MaterialRequeridoProyecto" (
	"id" SERIAL NOT NULL,
	"proyecto_id"	INTEGER NOT NULL,
	"descripcion"	TEXT NOT NULL,
	"tipo"	TEXT,
	"cantidad"	DECIMAL NOT NULL DEFAULT 1,
	"peso_kg"	DECIMAL NOT NULL DEFAULT 0,
	"estado"	TEXT NOT NULL DEFAULT 'Pendiente',
	"observaciones"	TEXT,
	PRIMARY KEY("id"),
	CONSTRAINT "MaterialRequeridoProyecto_proyecto_id_fkey" FOREIGN KEY("proyecto_id") REFERENCES "ProyectoEspecial"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "MovimientoInventarioMP" (
	"id" SERIAL NOT NULL,
	"materia_prima_id"	INTEGER NOT NULL,
	"fecha_hora"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"tipo_movimiento"	TEXT NOT NULL,
	"cantidad"	DECIMAL NOT NULL,
	"referencia_id"	TEXT,
	"orden_trabajo_id"	INTEGER,
	"imagen_remision_url"	TEXT,
	"cliente_id"	INTEGER,
	"updatedAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "MovimientoInventarioMP_cliente_id_fkey" FOREIGN KEY("cliente_id") REFERENCES "Cliente"("id") ON DELETE SET NULL ON UPDATE CASCADE,
	CONSTRAINT "MovimientoInventarioMP_materia_prima_id_fkey" FOREIGN KEY("materia_prima_id") REFERENCES "MateriaPrima"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
	CONSTRAINT "MovimientoInventarioMP_orden_trabajo_id_fkey" FOREIGN KEY("orden_trabajo_id") REFERENCES "OrdenTrabajo"("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "MovimientoProducto" (
	"id" SERIAL NOT NULL,
	"producto_id"	INTEGER NOT NULL,
	"fecha"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"tipo_movimiento"	TEXT NOT NULL,
	"cantidad"	INTEGER NOT NULL,
	"referencia"	TEXT,
	PRIMARY KEY("id"),
	CONSTRAINT "MovimientoProducto_producto_id_fkey" FOREIGN KEY("producto_id") REFERENCES "Producto"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "NotaTecnica" (
	"id" SERIAL NOT NULL,
	"proyecto_id"	INTEGER NOT NULL,
	"autor"	TEXT NOT NULL,
	"fecha"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"contenido"	TEXT NOT NULL,
	PRIMARY KEY("id"),
	CONSTRAINT "NotaTecnica_proyecto_id_fkey" FOREIGN KEY("proyecto_id") REFERENCES "ProyectoEspecial"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "OperacionCatalog" (
	"id" SERIAL NOT NULL,
	"nombre_operacion"	TEXT NOT NULL,
	"centro_trabajo"	TEXT,
	"orden"	INTEGER NOT NULL DEFAULT 0,
	"categoria_material_sugerido"	TEXT,
	"costo_hora"	DECIMAL DEFAULT 0,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "OrdenMantenimiento" (
	"id" SERIAL NOT NULL,
	"maquina_id"	INTEGER NOT NULL,
	"falla_id"	INTEGER,
	"tipo"	TEXT NOT NULL,
	"fecha_inicio"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"fecha_fin"	TIMESTAMP,
	"tecnico"	TEXT NOT NULL,
	"actividades"	TEXT,
	"repuestos"	TEXT,
	"tiempo_muerto_hrs"	REAL DEFAULT 0,
	"costo"	DECIMAL DEFAULT 0,
	"estado"	TEXT NOT NULL DEFAULT 'Abierta',
	"createdAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "OrdenMantenimiento_falla_id_fkey" FOREIGN KEY("falla_id") REFERENCES "ReporteFalla"("id") ON DELETE SET NULL ON UPDATE CASCADE,
	CONSTRAINT "OrdenMantenimiento_maquina_id_fkey" FOREIGN KEY("maquina_id") REFERENCES "Maquina"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "OrdenTrabajo" (
	"id" SERIAL NOT NULL,
	"numero_ot"	TEXT NOT NULL,
	"tipo_orden"	TEXT NOT NULL DEFAULT 'PRODUCCION_SERIE',
	"producto_id"	INTEGER,
	"cantidad_pedido"	INTEGER NOT NULL DEFAULT 0,
	"cantidad_fabricar"	INTEGER NOT NULL DEFAULT 0,
	"descripcion_proyecto"	TEXT,
	"cliente"	TEXT,
	"orden_compra_cliente"	TEXT,
	"fecha_creacion"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"fecha_entrega_req"	TIMESTAMP,
	"prioridad"	TEXT NOT NULL DEFAULT 'ESTANDAR',
	"estado_ot"	TEXT NOT NULL DEFAULT 'Pendiente',
	"acabado"	TEXT,
	"ancho_tira"	DECIMAL,
	"piezas_lamina"	TEXT,
	"imagen_url"	TEXT,
	"po_pdf_url"	TEXT,
	"costo_total_estimado"	DECIMAL DEFAULT 0,
	"costo_total_real"	DECIMAL DEFAULT 0,
	"precio_venta"	DECIMAL DEFAULT 0,
	"fecha_inicio_real"	TIMESTAMP,
	"fecha_fin_real"	TIMESTAMP,
	"duracion_total_real_min"	INTEGER DEFAULT 0,
	"pedido_id"	INTEGER,
	"updatedAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "OrdenTrabajo_pedido_id_fkey" FOREIGN KEY("pedido_id") REFERENCES "Pedido"("id") ON DELETE SET NULL ON UPDATE CASCADE,
	CONSTRAINT "OrdenTrabajo_producto_id_fkey" FOREIGN KEY("producto_id") REFERENCES "Producto"("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Pedido" (
	"id" SERIAL NOT NULL,
	"cliente"	TEXT,
	"orden_compra"	TEXT,
	"fecha_emision"	TIMESTAMP,
	"codigo"	TEXT,
	"referencia"	TEXT,
	"posicion"	TEXT,
	"descripcion"	TEXT,
	"cantidad"	INTEGER DEFAULT 0,
	"cantidad_fabricada"	INTEGER DEFAULT 0,
	"cantidad_en_inventario"	INTEGER DEFAULT 0,
	"cantidad_despachada"	INTEGER DEFAULT 0,
	"saldo_pendiente"	INTEGER DEFAULT 0,
	"fecha_entrega"	TEXT,
	"estado"	TEXT DEFAULT 'PENDIENTE',
	"precio_unitario"	DECIMAL DEFAULT 0,
	"valor_total"	DECIMAL DEFAULT 0,
	"producto_id"	INTEGER,
	"createdAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updatedAt"	TIMESTAMP NOT NULL,
	PRIMARY KEY("id"),
	CONSTRAINT "Pedido_producto_id_fkey" FOREIGN KEY("producto_id") REFERENCES "Producto"("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Personal" (
	"id" SERIAL NOT NULL,
	"nombre"	TEXT NOT NULL,
	"cedula"	TEXT NOT NULL,
	"cargo"	TEXT NOT NULL,
	"kpi_puntualidad"	REAL,
	"salario"	DECIMAL,
	"calificacion"	TEXT,
	"eficiencia"	REAL,
	"productividad"	REAL,
	"area"	TEXT NOT NULL DEFAULT '',
	"activo"	BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "PiezaProyecto" (
	"id" SERIAL NOT NULL,
	"proyecto_id"	INTEGER NOT NULL,
	"nombre"	TEXT NOT NULL,
	"cantidad"	INTEGER NOT NULL DEFAULT 1,
	"avance_fabricacion"	REAL NOT NULL DEFAULT 0,
	"requiere_montaje"	BOOLEAN NOT NULL DEFAULT false,
	"estado_montaje"	TEXT NOT NULL DEFAULT 'Pendiente',
	"observaciones"	TEXT,
	"plano_url_1"	TEXT,
	"plano_url_2"	TEXT,
	"ancho"	DECIMAL,
	"diametro"	DECIMAL,
	"espesor"	DECIMAL,
	"largo"	DECIMAL,
	"tipo_material"	TEXT,
	PRIMARY KEY("id"),
	CONSTRAINT "PiezaProyecto_proyecto_id_fkey" FOREIGN KEY("proyecto_id") REFERENCES "ProyectoEspecial"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "PlanMantenimiento" (
	"id" SERIAL NOT NULL,
	"maquina_id"	INTEGER NOT NULL,
	"tarea"	TEXT NOT NULL,
	"tipo_mtto"	TEXT NOT NULL DEFAULT 'Lubricación',
	"frecuencia"	TEXT NOT NULL DEFAULT 'Mensual',
	"frecuencia_dias"	INTEGER NOT NULL DEFAULT 30,
	"responsable"	TEXT NOT NULL,
	"checklist"	TEXT,
	"tiempo_estimado_min"	INTEGER,
	"ultima_ejecucion"	TIMESTAMP,
	"proxima_fecha"	TIMESTAMP,
	"createdAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "PlanMantenimiento_maquina_id_fkey" FOREIGN KEY("maquina_id") REFERENCES "Maquina"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "PrestamoHerramienta" (
	"id" SERIAL NOT NULL,
	"herramienta_id"	INTEGER NOT NULL,
	"personal_id"	INTEGER NOT NULL,
	"fecha_prestamo"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"fecha_devolucion"	TIMESTAMP,
	"cantidad"	INTEGER NOT NULL DEFAULT 1,
	"estado"	TEXT NOT NULL DEFAULT 'ACTIVO',
	"observaciones"	TEXT,
	PRIMARY KEY("id"),
	CONSTRAINT "PrestamoHerramienta_herramienta_id_fkey" FOREIGN KEY("herramienta_id") REFERENCES "HerramientaConsumible"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
	CONSTRAINT "PrestamoHerramienta_personal_id_fkey" FOREIGN KEY("personal_id") REFERENCES "Personal"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Producto" (
	"id" SERIAL NOT NULL,
	"sku_producto"	TEXT NOT NULL,
	"nombre_producto"	TEXT NOT NULL,
	"descripcion"	TEXT,
	"cliente_id"	INTEGER,
	"acabado"	TEXT,
	"imagen_url"	TEXT,
	"stock_actual"	INTEGER NOT NULL DEFAULT 0,
	"ancho_tira"	DECIMAL,
	"medidas_pieza"	TEXT,
	"piezas_lamina_4x8"	TEXT,
	"piezas_lamina_2x1"	TEXT,
	"empaque_de"	TEXT,
	"ubicacion"	TEXT,
	"plano_pdf_url"	TEXT,
	"activo"	BOOLEAN NOT NULL DEFAULT true,
	"precio_venta"	DECIMAL DEFAULT 0,
	PRIMARY KEY("id"),
	CONSTRAINT "Producto_cliente_id_fkey" FOREIGN KEY("cliente_id") REFERENCES "Cliente"("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ProyectoEspecial" (
	"id" SERIAL NOT NULL,
	"codigo"	TEXT NOT NULL,
	"cliente"	TEXT NOT NULL,
	"descripcion_tecnica"	TEXT NOT NULL,
	"tipo_proyecto"	TEXT NOT NULL,
	"responsable_tecnico"	TEXT NOT NULL,
	"fecha_inicio"	TIMESTAMP NOT NULL,
	"fecha_compromiso"	TIMESTAMP NOT NULL,
	"estado"	TEXT NOT NULL,
	"prioridad"	TEXT NOT NULL,
	"penalidad_retraso"	TEXT,
	"porcentaje_avance"	REAL NOT NULL DEFAULT 0,
	"indicador_riesgo"	TEXT NOT NULL DEFAULT 'Bajo',
	"bloqueado"	BOOLEAN NOT NULL DEFAULT false,
	"createdAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updatedAt"	TIMESTAMP NOT NULL,
	"foto_referencia_url"	TEXT,
	"plano_pdf_url"	TEXT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "RegistroPieza" (
	"id" SERIAL NOT NULL,
	"pieza_id"	INTEGER NOT NULL,
	"tipo"	TEXT NOT NULL,
	"fecha"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"descripcion"	TEXT NOT NULL,
	"avance_reportado"	REAL,
	PRIMARY KEY("id"),
	CONSTRAINT "RegistroPieza_pieza_id_fkey" FOREIGN KEY("pieza_id") REFERENCES "PiezaProyecto"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "RegistroTiempoLaboral" (
	"id" SERIAL NOT NULL,
	"personal_id"	INTEGER NOT NULL,
	"tipo"	TEXT NOT NULL,
	"fecha"	TIMESTAMP NOT NULL,
	"horas"	REAL DEFAULT 0,
	"motivo"	TEXT,
	"aprobado"	BOOLEAN NOT NULL DEFAULT false,
	"pagado"	BOOLEAN NOT NULL DEFAULT false,
	"fecha_creacion"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"costo_total"	DECIMAL DEFAULT 0,
	"horas_diurnas"	REAL DEFAULT 0,
	"horas_festivas"	REAL DEFAULT 0,
	"horas_nocturnas"	REAL DEFAULT 0,
	PRIMARY KEY("id"),
	CONSTRAINT "RegistroTiempoLaboral_personal_id_fkey" FOREIGN KEY("personal_id") REFERENCES "Personal"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ReporteFalla" (
	"id" SERIAL NOT NULL,
	"maquina_id"	INTEGER NOT NULL,
	"fecha_reporte"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"reportado_por"	TEXT NOT NULL,
	"descripcion"	TEXT NOT NULL,
	"prioridad"	TEXT NOT NULL DEFAULT 'Media',
	"estado"	TEXT NOT NULL DEFAULT 'Pendiente',
	PRIMARY KEY("id"),
	CONSTRAINT "ReporteFalla_maquina_id_fkey" FOREIGN KEY("maquina_id") REFERENCES "Maquina"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "RutaFabricacion" (
	"id" SERIAL NOT NULL,
	"producto_id"	INTEGER NOT NULL,
	"no_operacion"	INTEGER NOT NULL,
	"nombre_operacion"	TEXT NOT NULL,
	"centro_trabajo"	TEXT NOT NULL,
	"piezas_por_hora_estimado"	INTEGER,
	"tiempo_estandar"	DECIMAL,
	"activo"	BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id"),
	CONSTRAINT "RutaFabricacion_producto_id_fkey" FOREIGN KEY("producto_id") REFERENCES "Producto"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "TareaProduccion" (
	"id" SERIAL NOT NULL,
	"orden_trabajo_id"	INTEGER NOT NULL,
	"ruta_fabricacion_id"	INTEGER NOT NULL,
	"personal_id"	INTEGER,
	"maquina_id"	INTEGER,
	"estado_tarea"	TEXT NOT NULL DEFAULT 'Pendiente',
	"fecha_hora_inicio"	TIMESTAMP,
	"fecha_hora_fin"	TIMESTAMP,
	"tiempo_parada_min"	INTEGER NOT NULL DEFAULT 0,
	"cantidad_buena"	INTEGER DEFAULT 0,
	"cantidad_mala"	INTEGER DEFAULT 0,
	"motivo_rechazo"	TEXT,
	"costo_estimado"	DECIMAL DEFAULT 0,
	"costo_real"	DECIMAL DEFAULT 0,
	"duracion_real_min"	INTEGER DEFAULT 0,
	"updatedAt"	TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "TareaProduccion_maquina_id_fkey" FOREIGN KEY("maquina_id") REFERENCES "Maquina"("id") ON DELETE SET NULL ON UPDATE CASCADE,
	CONSTRAINT "TareaProduccion_orden_trabajo_id_fkey" FOREIGN KEY("orden_trabajo_id") REFERENCES "OrdenTrabajo"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
	CONSTRAINT "TareaProduccion_personal_id_fkey" FOREIGN KEY("personal_id") REFERENCES "Personal"("id") ON DELETE SET NULL ON UPDATE CASCADE,
	CONSTRAINT "TareaProduccion_ruta_fabricacion_id_fkey" FOREIGN KEY("ruta_fabricacion_id") REFERENCES "RutaFabricacion"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Usuario" (
	"id" SERIAL NOT NULL,
	"nombre"	TEXT NOT NULL,
	"email"	TEXT NOT NULL,
	"password_hash"	TEXT NOT NULL,
	"rol"	TEXT NOT NULL,
	PRIMARY KEY("id")
);
